 1	method binarySearch(a:array<int>, val:int) returns (pos:int)
 2	  requires a.Length > 0
 3	  requires forall i, j :: 0 <= i < j < a.Length ==> a[i] <= a[j]
 4	
 5	  ensures 0 <= pos < a.Length ==> a[pos] == val
 6	  ensures pos < 0 || pos >= a.Length  ==> forall i :: 0 <= i < a.Length ==> a[i] != val
 7	
 8	{
 9	  var left := 0;
10	  var right := a.Length;
11	  if a[left] > val || a[right-1] < val 
12	  {
13	    return -1;
14	  }
15	  while left < right
16	 
17	    invariant 0 <= left <= right <= a.Length
18	    invariant forall i :: 0 <= i < a.Length && !(left <= i < (right) + 1) ==> a[i] != val
19	
20	    decreases right - left
21	  {
22	    var med := (left + right) / 2;
23	    assert left <= med <= right;
24	    if a[med] < val
25	    {
26	      left := med + 1;
27	    }
28	    else if a[med] > val
29	    {
30	      right := med;
31	    }
32	    else
33	    {
34	      assert a[med] == val;
35	      pos := med;
36	      return;
37	    }
38	
39	  }
40	  return -1;
41	}

